contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public {
        c.SetMinSum(v); if (__ESBMC_reverted()) return;
        assert(c.MinSum() == v);
    }

    receive() external payable {}
}

